  "/app.css": { type: "text/css; charset=utf-8", body: ":root { color-scheme: light dark; --bg: #fff; --fg: #1b1f24; --muted: #59636e; --border: #d0d7de; --surface: #f6f8fa; --accent: #0969da; --warn: #9a6700; --err: #cf222e; --ok: #1a7f37; }\n@media (prefers-color-scheme: dark) { :root { --bg: #0d1117; --fg: #e6edf3; --muted: #8b949e; --border: #30363d; --surface: #161b22; --accent: #58a6ff; --warn: #d29922; --err: #f85149; --ok: #3fb950; } }\n* { box-sizing: border-box; }\nbody { margin: 0; background: var(--bg); color: var(--fg); font: 14px/1.45 system-ui, sans-serif; }\ncode, pre, .mono { font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 12px; }\n.muted { color: var(--muted); }\n.bar { display: flex; gap: 12px; align-items: center; padding: 8px 16px; border-bottom: 1px solid var(--border); background: var(--surface); }\n.bar h1 { font-size: 16px; margin: 0; }\n.spacer { flex: 1; }\n.badge { display: inline-block; padding: 0 6px; border: 1px solid var(--border); border-radius: 10px; font-size: 11px; margin-left: 4px; }\n.badge.warn { color: var(--warn); border-color: var(--warn); }\n.badge.err { color: var(--err); border-color: var(--err); }\n.badge.ok { color: var(--ok); border-color: var(--ok); }\n.banner, .notice { padding: 6px 16px; }\n.banner { background: var(--surface); border-bottom: 2px solid var(--warn); color: var(--warn); }\n.notice:empty { display: none; }\n.notice { color: var(--err); }\nbutton { font: inherit; padding: 3px 10px; border: 1px solid var(--border); border-radius: 4px; background: var(--surface); color: var(--fg); cursor: pointer; }\nbutton[aria-pressed=\"true\"], button[aria-selected=\"true\"] { background: var(--accent); color: #fff; border-color: var(--accent); }\n:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }\n.layout { display: grid; grid-template-columns: minmax(300px, 38%) 1fr; height: calc(100vh - 80px); }\nnav { overflow: auto; border-right: 1px solid var(--border); }\nmain { overflow: auto; padding: 12px 16px; }\n.filters { display: flex; flex-wrap: wrap; gap: 6px; padding: 8px; border-bottom: 1px solid var(--border); }\n.filters label { display: flex; flex-direction: column; font-size: 11px; color: var(--muted); }\n.filters input, .filters select { font: inherit; width: 120px; padding: 2px 4px; background: var(--bg); color: var(--fg); border: 1px solid var(--border); border-radius: 3px; }\n.list { list-style: none; margin: 0; padding: 0; }\n.list li button.row { display: block; width: 100%; text-align: left; border: 0; border-bottom: 1px solid var(--border); border-radius: 0; background: transparent; padding: 6px 8px; }\n.list li button.row[aria-current=\"true\"] { background: var(--surface); box-shadow: inset 3px 0 var(--accent); }\n.row .line1 { display: flex; gap: 6px; align-items: baseline; flex-wrap: wrap; }\n.row .line2 { color: var(--muted); font-size: 12px; overflow-wrap: anywhere; }\n.lane { position: relative; height: 4px; margin-top: 3px; background: var(--surface); }\n.lane > span { position: absolute; top: 0; height: 4px; background: var(--accent); }\n.more { padding: 8px; display: flex; gap: 8px; }\n.tabs { display: flex; gap: 4px; margin: 10px 0; flex-wrap: wrap; }\ntable { border-collapse: collapse; width: 100%; margin: 6px 0 12px; }\nth, td { text-align: left; vertical-align: top; padding: 3px 8px; border-bottom: 1px solid var(--border); overflow-wrap: anywhere; }\nth { color: var(--muted); font-weight: 600; width: 22%; }\npre { background: var(--surface); border: 1px solid var(--border); padding: 8px; overflow: auto; white-space: pre-wrap; overflow-wrap: anywhere; max-height: 60vh; }\n.warnings { border-left: 3px solid var(--warn); padding: 4px 10px; margin: 8px 0; background: var(--surface); }\n.derived { color: var(--warn); font-size: 12px; }\nh2, h3 { margin: 14px 0 4px; }\nh2 { font-size: 15px; }\nh3 { font-size: 13px; color: var(--muted); }\n.sr { position: absolute; left: -9999px; }\n" },
